t.add("admin.help.observatoire.confirm-delete-observatory(%name%)", "Etes-vous s\u00fbr de vouloir supprimer l'observatoire \u00ab\u00a0%name%\u00a0\u00bb ?", "messages", "fr");
t.add("admin.help.observatoire.confirm-delete-observatory-info", "<strong style=\"color:red\">Les bar\u00e8mes, bassins, cours d'eau et\/ou DOI concern\u00e9s seront \u00e9galement supprim\u00e9s.<\/strong>", "messages", "fr");
t.add("admin.help.observatoire.warning-delete-observatory-info-redirect", "Ceci est l'observatoire courant, si vous le supprimer vous serez redirig\u00e9 sur la page d'accueil de tous les observatoires.", "messages", "fr");
t.add("admin.help.observatoire.titre-info", "Exemple: \u00abAMMA-CATCH: a hydrological, meteorological and ecological observatory on West Africa\u00bb", "messages", "fr");
