t.add("admin.help.observatoire.theiaCode-message", "<strong style=\"color:red; font-size: 10px\">[Champ pour Theia\/Ozcar]<\/strong><br>Correspond aux 4 premi\u00e8res lettres en majuscule de l'Observatoire. <br>Les identifiants font r\u00e9f\u00e9rences au mod\u00e8le de donn\u00e9es pivot Theia\/Ozcar (Annexe 1 page 15) : <a href='https:\/\/theia-ozcar.gricad-pages.univ-grenoble-alpes.fr\/doc-producer\/producer-documentation.html#modele-de-donnees-pivot-description-et-implementation-en-json' target='_blank'>Ici<\/a> ", "messages", "fr");
t.add("admin.help.observatoire.theiaPassword-message", "Le mot de passe ne s'affiche pas dans ce champ pour des raisons de confidentialit\u00e9. Le laisser en \u00e9tat pour le conserver.", "messages", "fr");
t.add("admin.help.observatoire.doi-principal-message", " Theia\/Ozcar demande un seul DOI pour ses ressources en ligne. Ajouter ici le DOI principal de l'observatoire. ", "messages", "fr");
t.add("admin.help.dataset.contact", "<strong style=\"color:red; font-size: 10px\">[Champ pour Theia\/Ozcar]<\/strong><br>Theia\/Ozcar demande la pr\u00e9sence obligatoire d'au moins un Project Leader", "messages", "fr");
t.add("admin.help.dataset.description", "Le r\u00e9sum\u00e9 doit d\u00e9crire la ressource de fa\u00e7on compr\u00e9hensible par l\u2019utilisateur. Pour un producteur, il s\u2019agit en particulier de d\u00e9finir au mieux l\u2019information ou le ph\u00e9nom\u00e8ne repr\u00e9sent\u00e9 dans la donn\u00e9e. On va donc y trouver des \u00e9l\u00e9ments de d\u00e9finition, mais aussi \u00e9ventuellement une indication sommaire de la zone couverte ou le cas \u00e9ch\u00e9ant, des informations sur les particularit\u00e9s de la version du jeu de donn\u00e9es.", "messages", "fr");
t.add("admin.help.dataset.genealogy", "D\u00e9crit la g\u00e9n\u00e9alogie d'un jeu de donn\u00e9es, i.e. l\u2019historique du jeu de donn\u00e9es et, s\u2019il est connu, le cycle de vie de celui-ci, depuis l\u2019acquisition et la saisie de l\u2019information jusqu\u2019\u00e0 sa compilation avec d\u2019autres jeux et les variantes de sa forme actuelle. Il s\u2019agit d\u2019apporter une description litt\u00e9rale et concise soit de l\u2019histoire du jeu de donn\u00e9es, soit des  moyens,  proc\u00e9dures  ou  traitements  informatiques  mis  en  \u0153uvre  au  moment  de l\u2019acquisition dujeu de donn\u00e9es.", "messages", "fr");
t.add("admin.help.site.warning-site-has-stations", "Pour supprimer ce site exp\u00e9rimental vous devez d'abord en dissocier la station suivante :|Pour supprimer ce site exp\u00e9rimental vous devez d'abord en dissocier les stations suivantes :", "messages", "fr");
t.add("admin.help.station.code", "Les caract\u00e8res accentu\u00e9s et sp\u00e9ciaux de ce code seront automatiquement remplac\u00e9s.", "messages", "fr");
t.add("admin.help.station.codeAlternatif", "Suite de codes de station s\u00e9par\u00e9s par des \u00ab\u00a0;\u00a0\u00bb et du type \u00ab\u00a0Format=CODE\u00a0\u00bb, utilis\u00e9s pour des exports de chroniques dans des formats non-BDOH. Exemple : Hydro2 = MON_CODE_HYDRO2", "messages", "fr");
t.add("admin.help.station.latlong", "Lambert93 - EPSG:2154 (m\u00e8tres)", "messages", "fr");
t.add("admin.help.station.warning-station-has-time-series", "Cette station ne peut pas \u00eatre supprim\u00e9e car elle contient la chronique suivante :|Cette station ne peut pas \u00eatre supprim\u00e9e car elle contient les chroniques suivantes :", "messages", "fr");
t.add("admin.help.station.warning-station-has-basins", "Cette station est utilis\u00e9e par le bassin suivant en tant que station exutoire :|Cette station est utilis\u00e9e par les bassins suivants en tant que station exutoire :", "messages", "fr");
t.add("admin.help.station.town-name-is-case-sensitive", "<u>Attention : le filtre de recherche est sensible \u00e0 la casse, les communes ont toutes des majuscules \u00e0 leur nom et les communes avec des noms compos\u00e9s ont des tirets et non des espaces (ex. : Saint-Germain-sur-l'Arbresle, Sainte-Foy-l\u00e8s-Lyon, etc.), dans le doute faites une recherche sur une partie du nom qui ne peut pas avoir de majuscule ni de tiret ou faites une recherche sur le code postal.<\/u>", "messages", "fr");
t.add("admin.help.station.confirm-delete-station(%name%)", "Etes-vous s\u00fbr de vouloir supprimer la station \u00ab\u00a0%name%\u00a0\u00bb ?", "messages", "fr");
t.add("admin.help.station.confirm-delete-station-info", "Les bassins concern\u00e9s ne seront pas supprim\u00e9s, ils perdront simplement leur station exutoire.", "messages", "fr");
t.add("admin.help.chronique.code", "Les caract\u00e8res accentu\u00e9s et sp\u00e9ciaux de ce code seront automatiquement remplac\u00e9s.", "messages", "fr");
t.add("admin.help.chronique.libelle", "Un texte court d\u00e9crivant la chronique de mani\u00e8re unique, sp\u00e9cifique...", "messages", "fr");
