t.add("admin.help.chronique.warning-no-export-options-were-defined", "<strong>Attention :<\/strong> les options d'export \u00e0 pas de temps fixe n'ont pas encore \u00e9t\u00e9 d\u00e9finies pour cette chronique. Des valeurs par d\u00e9faut ont \u00e9t\u00e9 automatiquement assign\u00e9es. Merci de les v\u00e9rifier\/\u00e9diter puis d'enregistrer les modifications.", "messages", "fr");
