t.add("admin.help.chronique.update-unite-cumul", "Si vous autorisez l'export de cumuls pour cette chronique pensez \u00e0 v\u00e9rifier ou mettre \u00e0 jour l'unit\u00e9 des cumuls ci-dessous.", "messages", "fr");
