t.add("admin.help.familleParametres.warning-familleParametres-has-children", "Cette famille de param\u00e8tres ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par la famille suivante (en tant que famille m\u00e8re) :|Cette famille de param\u00e8tres ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par les familles suivantes (en tant que famille m\u00e8re) :", "messages", "fr");
t.add("admin.help.familleParametres.warning-familleParametres-has-types", "Cette famille de param\u00e8tres ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par le type de param\u00e8tre suivante :|Cette famille de param\u00e8tres ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par les types de param\u00e8tres suivants :", "messages", "fr");
t.add("admin.help.familleParametres.help-prefix", "Le pr\u00e9fixe est utilis\u00e9 pour ordonner les familles de m\u00eame niveau (par exemple : 001, 002, 003, ...), il n'est pas affich\u00e9.", "messages", "fr");
t.add("admin.help.familleParametres.help-familleParente", "Les familles filles et descendantes ne sont pas pr\u00e9sentes dans cette liste de s\u00e9lection. Vous pouvez aussi supprimer la famille m\u00e8re en utilisant la petite croix \u00e0 droite.", "messages", "fr");
t.add("admin.help.typeParametre.warning-typeParametre-has-time-series", "Ce type de param\u00e8tre ne peut pas \u00eatre supprim\u00e9 car il est utilis\u00e9 par la chronique suivante :|Ce type de param\u00e8tre ne peut pas \u00eatre supprim\u00e9 car il est utilis\u00e9 par les chroniques suivantes :", "messages", "fr");
t.add("admin.help.typeParametre.warning-no-family-defined", "<strong>Attention :<\/strong> Ce type de param\u00e8tre n'a pas de famille de param\u00e8tres (la premi\u00e8re famille est s\u00e9lectionn\u00e9e par d\u00e9faut). Vous devez s\u00e9lectionner une famille de param\u00e8tres pour ce type et enregistrer la modification.", "messages", "fr");
t.add("admin.help.unite.warning-unit-has-time-series", "Cette unit\u00e9 ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par la chronique suivante :|Cette unit\u00e9 ne peut pas \u00eatre supprim\u00e9e car elle est utilis\u00e9e par les chroniques suivantes :", "messages", "fr");
