t.add("admin.help.unite.warning-unit-has-parameter-types", "Cette unit\u00e9 est utilis\u00e9e par le type de param\u00e8tre suivant :|Cette unit\u00e9 est utilis\u00e9e par les types de param\u00e8tre suivants :", "messages", "fr");
